const canvas=$('game'),ctx=canvas.getContext('2d');
let W=0,H=0,ARENA={x:30,y:30,w:0,h:0},borderPoints=[],groundMarks=[];
const isTouch=matchMedia('(pointer: coarse)').matches;if(isTouch)document.body.classList.add('is-touch');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rand=(a,b)=>a+Math.random()*(b-a);
const irand=(a,b)=>Math.floor(rand(a,b+1));
const choice=a=>a[Math.floor(Math.random()*a.length)];
const normAngle=a=>{while(a>Math.PI)a-=Math.PI*2;while(a<-Math.PI)a+=Math.PI*2;return a};
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
const STORAGE='stickswing_living_sketchbook';

const chapterThemes=[
  {name:'THE FIRST PAGE', vars:{bg:'#15130f',paper:'#1e1a14',paper2:'#262018',paper3:'#31271f',ink:'#e9e3d3',inkDim:'#a49b86',blood:'#b23a2e',bloodDark:'#72271f',gold:'#d9a441',goldDark:'#856527',safe:'#5b8a72',violet:'#8f79a8',cold:'#6f95b4'}},
  {name:'RED INK', vars:{bg:'#180f10',paper:'#251718',paper2:'#2d1d1f',paper3:'#382426',ink:'#f0e4dc',inkDim:'#b79f96',blood:'#cb4940',bloodDark:'#7c2b26',gold:'#d7a860',goldDark:'#8f6a31',safe:'#63816d',violet:'#9f82b8',cold:'#6f8fa8'}},
  {name:'BURNT PAGES', vars:{bg:'#16120d',paper:'#241b12',paper2:'#2d2115',paper3:'#38281a',ink:'#f0e2c4',inkDim:'#b6a482',blood:'#b85334',bloodDark:'#76301f',gold:'#e0b55b',goldDark:'#8c6a25',safe:'#6b8f69',violet:'#9e84a7',cold:'#7a8ca0'}},
  {name:'THE BACK COVER', vars:{bg:'#100f14',paper:'#191923',paper2:'#20202b',paper3:'#2a2a38',ink:'#e5e6ef',inkDim:'#9b9dae',blood:'#c15566',bloodDark:'#7a3340',gold:'#ceb96d',goldDark:'#8b7630',safe:'#5e7f87',violet:'#9788cb',cold:'#7b98bf'}}
];
function applyTheme(index){const theme=chapterThemes[clamp(index,0,chapterThemes.length-1)].vars;for(const [k,v] of Object.entries(theme))document.documentElement.style.setProperty('--'+k,v)}

const settings={master:1,sfx:.9,music:.42,musicEnabled:true,track:'lofi',reducedShake:false,autoMap:true};
function loadSettings(){try{Object.assign(settings,JSON.parse(localStorage.getItem(STORAGE+'_settings')||'{}'))}catch{}}
function saveSettings(){localStorage.setItem(STORAGE+'_settings',JSON.stringify(settings))}
loadSettings();

let actx=null,musicTimer=null,musicStep=0,musicPhrase=0;
const tracks={
  lofi:{name:'Paper Drifter',tempo:330,bass:[0,-5,-3,-7],lead:[0,2,4,7,4,2,0,null],pad:[0,null,7,null]},
  ember:{name:'Ember Waltz',tempo:290,bass:[0,-3,-5,-7],lead:[7,5,4,2,4,5,7,9],pad:[0,null,4,null]},
  dream:{name:'Margin Bloom',tempo:360,bass:[0,-7,-5,-3],lead:[0,7,9,7,5,4,2,0],pad:[0,null,5,null]}
};
function ensureAudio(){if(!actx){try{actx=new (window.AudioContext||window.webkitAudioContext)()}catch{}}if(actx&&actx.state==='suspended')actx.resume()}
function tone(freq,dur,type='sine',gain=.08,slide=null,delay=0){if(!actx||settings.master<=0)return;const t=actx.currentTime+delay,o=actx.createOscillator(),g=actx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),t+dur*.85);const finalGain=gain*settings.master;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(finalGain,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(actx.destination);o.start(t);o.stop(t+dur+.03)}
function sfx(name){if(!actx||settings.master<=0||settings.sfx<=0)return;const g=settings.sfx;const p=rand(.93,1.07);if(name==='swing'){tone(220*p,.07,'triangle',.09*g,140*p);tone(420*p,.05,'sine',.024*g,260*p,.014)}
 else if(name==='hit'){tone(105*p,.05,'square',.13*g,72*p);tone(670*p,.03,'triangle',.03*g,280*p)}
 else if(name==='crit'){tone(84,.08,'square',.14*g,44);tone(920,.07,'triangle',.05*g,420)}
 else if(name==='hurt'){tone(92,.15,'square',.12*g,50)}
 else if(name==='death'){tone(520*p,.11,'sawtooth',.06*g,860*p);tone(150*p,.1,'square',.05*g,80*p,.03)}
 else if(name==='buy'){tone(540,.07,'sine',.06*g,720);tone(720,.07,'sine',.05*g,920,.06)}
 else if(name==='deny'){tone(110,.08,'square',.06*g,88)}
 else if(name==='heal'){tone(430,.18,'sine',.06*g,720)}
 else if(name==='dash'){tone(250,.05,'triangle',.045*g,640)}
 else if(name==='wave'){tone(290,.2,'triangle',.05*g,440);tone(440,.18,'sine',.035*g,620,.08)}
 else if(name==='boss'){tone(90,.42,'sawtooth',.08*g,55);tone(180,.34,'square',.04*g,90,.08)}
 else if(name==='block'){tone(180,.06,'square',.08*g,120);tone(460,.03,'triangle',.025*g,260)}
 else if(name==='parry'){tone(520,.08,'triangle',.065*g,860);tone(880,.05,'sine',.045*g,1100,.04)}
 else if(name==='magic'){tone(420,.11,'sine',.05*g,760);tone(690,.09,'triangle',.036*g,980,.03)}
 else if(name==='level'){tone(350,.16,'triangle',.05*g,520);tone(520,.14,'sine',.04*g,760,.06)}
 else if(name==='gameover'){tone(190,.55,'sawtooth',.07*g,50)}
}
function noteToHz(n,base=220){return base*Math.pow(2,n/12)}
function musicTick(){if(!actx||!settings.musicEnabled||settings.music<=0)return;const tr=tracks[settings.track]||tracks.lofi;const step=musicStep%8,bassIdx=musicPhrase%tr.bass.length,padIdx=musicPhrase%tr.pad.length;const mg=settings.music*.09;const bass=tr.bass[bassIdx];tone(noteToHz(bass,110),.23,'triangle',mg*.9);const lead=tr.lead[step];if(lead!==null)tone(noteToHz(lead,220),.17,'sine',mg*.7,lead+2);const pad=tr.pad[padIdx];if(step%2===0&&pad!==null)tone(noteToHz(pad,165),.52,'triangle',mg*.35);musicStep++;if(step===7)musicPhrase++}
function restartMusic(){if(musicTimer)clearInterval(musicTimer);musicStep=0;musicPhrase=0;if(settings.musicEnabled){musicTimer=setInterval(()=>{ensureAudio();musicTick()},(tracks[settings.track]||tracks.lofi).tempo)}}

